public static int maxRegions(int N) {
    if (N < 0) {
        throw new IllegalArgumentException("Number of triangles cannot be negative");
    }
    if (N == 0) {
        return 1; // No triangles, just the plane itself
    }
    // The formula to calculate the maximum number of regions is derived from the problem
    // of finding the maximum number of regions a plane can be divided into by N lines.
    // For triangles, each new triangle can intersect all previous triangles in a way
    // that maximizes the number of regions.
    // The formula is: R(N) = 2 * N^2 + 2 * N + 1
    return 2 * N * N + 2 * N + 1;
}

