    for (int i = 0; i < s.length(); i++) {
        value = (value << 1) & mask | (s.charAt(i) - '0');
        if (i >= k - 1 && !found[value]) {
            found[value] = true;
            count++;
            if (count == totalPossible) {
                return true;
            }
        }
    }

    return false;
}

